sys_script_include.script:
function IsValidPluginId(strPluginId)
{
	strPluginId = GetStringValue(strPluginId);
	if (strPluginId == '')
	{
		return false;
	}
	if (strPluginId.length > 100)
	{
		return false;
	}
	if (strPluginId.length <= 5)
	{
		return false;
	}	

	var aExceptions = [
		'rome.glide.core.automation'
		];
	if (ArrayValueExists(aExceptions,strPluginId) == true)
	{
		return true;
	}

	var aPrefixes = [
		'com.',
		'upgrade.'
		];
	var bPrefixFound = false;
	for (nPrefix = 0; nPrefix < aPrefixes.length; nPrefix++)
	{
		var strPrefix = aPrefixes[nPrefix];
		if (strPluginId.indexOf(strPrefix) == 0)
		{
			bPrefixFound = true;
			break;
		}
	}
	if (bPrefixFound == false)
	{
		return false;
	}


	var aSections = strPluginId.split('.');
	for (var nSection = 0; nSection < aSections.length; nSection++)
	{
		var strSection = aSections[nSection];
		if (IsSnakeCase(strSection) == false)
		{
			return false;
		}
	}

	return true;
}
